  /* ── The catalog record: AnA's suggestion, a person's decision (S4, D5) ──
     What AnA recorded about the current version (kind, purpose, summary, key
     data), who proposed it (model, turn) and whether a person confirmed or
     corrected it. The writer (document-catalog-governance.service.ts) checks
     the role, the reason, the vocabulary and program ownership, and commits
     each decision with one chained audit row; these routes only carry it. */
  router.get('/:id/documents/:documentId/catalog', async (req: Request, res: Response) => {
    const orgId = resolveOrgId(req);
    if (!orgId) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    try {
      const { readCatalogRecord } = await import('../../services/vault/document-catalog-governance.service.js');
      const record = await readCatalogRecord({
        programId: String(req.params.id ?? ''), documentId: String(req.params.documentId ?? ''), organizationId: orgId,
        userId: governedActorId(req),
      });
      if (!record) return res.status(404).json({ success: false, error: 'NOT_FOUND' });
      return res.json({ success: true, data: record });
    } catch (err) {
      logger.error('vault catalog record read failed', { err: err instanceof Error ? err.message : String(err) });
      return res.status(500).json({ success: false, error: 'CATALOG_UNAVAILABLE',
        message: "This document's catalog record could not be read. Nothing is shown rather than a record that may be wrong." });
    }
  });

  const reviewCatalog = (action: 'confirm' | 'correct') => async (req: Request, res: Response) => {
    const orgId = resolveOrgId(req);
    if (!orgId) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    const body = (req.body ?? {}) as Record<string, unknown>;
    const text = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined);
    if ('expectedExtractedTextSha256' in body && typeof body.expectedExtractedTextSha256 !== 'string') {
      return res.status(400).json({ success: false, error: 'INVALID_EXTRACTED_TEXT_HASH',
        message: 'The shown source text must be identified by its SHA-256 digest.' });
    }
    try {
      const { reviewCatalogRecord } = await import('../../services/vault/document-catalog-governance.service.js');
      const outcome = await reviewCatalogRecord({
        programId: String(req.params.id ?? ''),
        documentId: String(req.params.documentId ?? ''),
        organizationId: orgId,
        // From the session only; the service refuses a request with none.
        userId: governedActorId(req),
        action,
        expectedContentHash: text(body.contentHash),
        expectedExtractedTextSha256: text(body.expectedExtractedTextSha256),
        expectedRevision: text(body.revision),
        documentKind: text(body.documentKind),
        purpose: text(body.purpose),
        summary: text(body.summary),
        reason: body.reason,
        ipAddress: req.ip,
        userAgent: req.headers['user-agent'],
      });
      if (!outcome.ok) {
        return res.status(outcome.status).json({ success: false, error: outcome.code, message: outcome.message });
      }
      return res.json({ success: true, state: outcome.state, changes: outcome.changes });
    } catch (err) {
      logger.error(`vault catalog ${action} failed`, { err: err instanceof Error ? err.message : String(err) });
      return res.status(500).json({ success: false, error: 'CATALOG_NOT_SAVED', message: 'The catalog record could not be saved. Nothing was changed.' });
    }
  };
  router.post('/:id/documents/:documentId/catalog/confirm', requireEditorAccess, reviewCatalog('confirm'));
  router.post('/:id/documents/:documentId/catalog/correct', requireEditorAccess, reviewCatalog('correct'));

  /* ── Document relationships (plan critique 15, D2) ─────────────────────
     One version names the documents that support it, that it references or
     that it is based on: the replacement for the parentDocumentId VR-05
     refused. vault-relationships.ts checks the role, the organisation and the
     vocabulary, and writes each change with a chained row on both documents.
     A relationship is removed with a reason, never deleted. */
  const relationshipFailure = (res: Response, err: unknown, what: string) => {
    logger.error(`vault relationships ${what} failed`, { err: err instanceof Error ? err.message : String(err) });
    return res.status(500).json({ success: false, error: 'RELATIONSHIPS_UNAVAILABLE',
      message: what === 'read'
        ? "This document's relationships could not be read. Nothing is shown rather than an incomplete list."
        : 'The relationship could not be saved. Nothing was changed.' });
  };

  router.get('/:id/documents/:documentId/relationships', async (req: Request, res: Response) => {
    const orgId = resolveOrgId(req);
    if (!orgId) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    const id = String(req.params.id ?? '');
    if (!UUID_RE.test(id)) return res.status(404).json({ success: false, error: 'NOT_FOUND' });
    try {
      const { listRelationships } = await import('../../services/vault/vault-relationships.js');
      const out = await listRelationships(pool, { programId: id, organizationId: orgId, documentId: String(req.params.documentId ?? '') });
      if (!out.ok) return res.status(out.status).json({ success: false, error: out.code, message: out.message });
      return res.json({ success: true, data: { relationships: out.relationships } });
    } catch (err) {
      return relationshipFailure(res, err, 'read');
    }
  });

  router.post('/:id/documents/:documentId/relationships', requireEditorAccess, async (req: Request, res: Response) => {
    const orgId = resolveOrgId(req);
    if (!orgId) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const { addRelationship } = await import('../../services/vault/vault-relationships.js');
      const out = await addRelationship({
        programId: String(req.params.id),
        organizationId: orgId,
        userId: (req as any).user?.id ?? null,
        documentId: String(req.params.documentId ?? ''),
        toDocumentId: body.toDocumentId,
        type: body.type,
        note: body.note,
        ipAddress: req.ip,
        userAgent: req.headers['user-agent'],
      });
      if (!out.ok) return res.status(out.status).json({ success: false, error: out.code, message: out.message });
      return res.status(201).json({ success: true, data: { id: out.id } });
    } catch (err) {
      return relationshipFailure(res, err, 'write');
    }
  });

  router.post('/:id/relationships/:relationshipId/remove', requireEditorAccess, async (req: Request, res: Response) => {
    const orgId = resolveOrgId(req);
    if (!orgId) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const { removeRelationship } = await import('../../services/vault/vault-relationships.js');
      const out = await removeRelationship({
        programId: String(req.params.id),
        organizationId: orgId,
        userId: (req as any).user?.id ?? null,
        relationshipId: String(req.params.relationshipId ?? ''),
        reason: body.reason,
        ipAddress: req.ip,
        userAgent: req.headers['user-agent'],
      });
      if (!out.ok) return res.status(out.status).json({ success: false, error: out.code, message: out.message });
      return res.json({ success: true });
    } catch (err) {
      return relationshipFailure(res, err, 'write');
    }
  });

  /* ── Review annotations (plan critique 15, D2/D5) ──────────────────────
     A reviewer annotates a version with a comment or a change request,
     anchored to the whole version, a page, or a passage of its extracted
     text; others reply; it is resolved with a note or retracted by its
     author with a reason (vault-annotations.ts, and the record's own guards
     in migrations/20261001_vault_version_annotations.sql). Reading the text
     to choose a passage is recorded, or nothing is served. Writes are behind
     the governed-write gate; the service checks the role again. */
  const annotationFailure = (res: Response, err: unknown, what: 'read' | 'write') => {
    const message = err instanceof Error ? err.message : String(err);
    if (isMissingStore(err)) {
      return res.status(503).json({ success: false, error: 'ANNOTATIONS_STORE_UNAVAILABLE',
        message: `Review annotations are not provisioned in this environment. ${what === 'read' ? 'Nothing is shown.' : 'Nothing was changed.'}` });
    }
    if (/^(VAULT_ANNOTATION_REFUSED|IMMUTABILITY_VIOLATION)/.test(message)) {
      logger.warn('vault annotation refused by its record', { message });
      return res.status(409).json({ success: false, error: 'ANNOTATION_REFUSED', message: 'The annotation record refused this change. Nothing was changed.' });
    }
    logger.error(`vault annotations ${what} failed`, { err: message });
    return res.status(500).json({ success: false, error: 'ANNOTATIONS_UNAVAILABLE',
      message: what === 'read'
        ? "This document's annotations could not be read. Nothing is shown rather than an incomplete list."
        : 'The annotation could not be saved. Nothing was changed.' });
  };
  const annotationActor = (req: Request) => ({
    programId: String(req.params.id ?? ''),
    organizationId: resolveOrgId(req) as number,
    userId: governedActorId(req),
    ipAddress: req.ip,
    userAgent: req.headers['user-agent'],
  });
  const answer = (res: Response, out: { ok: boolean } & Record<string, unknown>, created = false) => {
    if (!out.ok) return res.status(out.status as number).json({ success: false, error: out.code, message: out.message });
    const data = Object.fromEntries(Object.entries(out).filter(([k]) => k !== 'ok'));
    return res.status(created ? 201 : 200).json({ success: true, data });
  };

  router.get('/:id/documents/:documentId/annotations', async (req: Request, res: Response) => {
    const orgId = resolveOrgId(req);
    if (!orgId) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    try {
      const { listAnnotations } = await import('../../services/vault/vault-annotations.js');
      return answer(res, await listAnnotations(pool, {
        programId: String(req.params.id ?? ''), organizationId: orgId, documentId: String(req.params.documentId ?? ''),
      }));
    } catch (err) {
      return annotationFailure(res, err, 'read');
    }
  });

  router.get('/:id/documents/:documentId/text', async (req: Request, res: Response) => {
    if (!resolveOrgId(req)) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    try {
      const { readAnnotatableText } = await import('../../services/vault/vault-annotations.js');
      return answer(res, await readAnnotatableText({
        ...annotationActor(req), documentId: String(req.params.documentId ?? ''), from: req.query.from, length: req.query.length,
      }));
    } catch (err) {
      if ((err as { code?: unknown })?.code === 'AUDIT_WRITE_FAILED') {
        logger.error('vault text read not recorded', { err: err instanceof Error ? err.message : String(err) });
        return res.status(500).json({ success: false, error: 'AUDIT_WRITE_FAILED',
          message: 'The text was not shown because the read could not be recorded in the audit trail. Nothing was sent.' });
      }
      return annotationFailure(res, err, 'read');
    }
  });

  router.post('/:id/documents/:documentId/annotations', requireEditorAccess, async (req: Request, res: Response) => {
    if (!resolveOrgId(req)) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const { postAnnotation } = await import('../../services/vault/vault-annotations.js');
      return answer(res, await postAnnotation({
        ...annotationActor(req), documentId: String(req.params.documentId ?? ''), kind: body.kind, body: body.body, anchor: body.anchor,
      }), true);
    } catch (err) {
      return annotationFailure(res, err, 'write');
    }
  });

  router.post('/:id/annotations/:annotationId/replies', requireEditorAccess, async (req: Request, res: Response) => {
    if (!resolveOrgId(req)) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    try {
      const { replyToAnnotation } = await import('../../services/vault/vault-annotations.js');
      return answer(res, await replyToAnnotation({
        ...annotationActor(req), annotationId: String(req.params.annotationId ?? ''), body: (req.body ?? {}).body,
      }), true);
    } catch (err) {
      return annotationFailure(res, err, 'write');
    }
  });

  router.post('/:id/annotations/:annotationId/resolve', requireEditorAccess, async (req: Request, res: Response) => {
    if (!resolveOrgId(req)) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const { resolveAnnotation } = await import('../../services/vault/vault-annotations.js');
      return answer(res, await resolveAnnotation({
        ...annotationActor(req), annotationId: String(req.params.annotationId ?? ''), note: body.note,
        addressedInVersionId: body.addressedInVersionId,
      }));
    } catch (err) {
      return annotationFailure(res, err, 'write');
    }
  });

  router.post('/:id/annotations/:annotationId/retract', requireEditorAccess, async (req: Request, res: Response) => {
    if (!resolveOrgId(req)) return res.status(403).json({ success: false, error: 'FORBIDDEN' });
    try {
      const { retractAnnotation } = await import('../../services/vault/vault-annotations.js');
      return answer(res, await retractAnnotation({
        ...annotationActor(req), annotationId: String(req.params.annotationId ?? ''), reason: (req.body ?? {}).reason,
      }));
    } catch (err) {
      return annotationFailure(res, err, 'write');
    }
  });

  return router;
}

/**
 * AnA session bootstrap — pure ranking + formatting core (no DB, no I/O).
 *
 * Split from ana-session-bootstrap.ts so the selection/formatting logic is
 * directly unit-testable without dragging in the database. The DB loaders live
 * in ana-session-bootstrap.ts and call these.
 */

export interface BootstrapAtom {
  title: string;
  content: string;
  category?: string | null;
  importance?: string | null;
  isVerified?: boolean | null;
  confidence?: number | null;
  createdAt?: Date | string | null;
}

export interface OutcomeLesson {
  capabilityKey: string;
  outcome: string;
  documentType?: string | null;
  lessonsLearned?: string | null;
}

/**
 * Decide whether to auto-rehydrate session context for a chat turn. Pure so the
 * gating is testable without the route. Fires only at session start (no prior
 * messages in the thread), when an org is present, and unless explicitly
 * disabled — so prior context loads once per session without re-injecting every
 * turn.
 */
export function shouldAutoBootstrap(opts: {
  priorMessageCount: number;
  organizationId?: number | null;
  disabled?: boolean;
}): boolean {
  if (opts.disabled) return false;
  if (!opts.organizationId) return false;
  return opts.priorMessageCount === 0;
}

const IMPORTANCE_WEIGHT: Record<string, number> = {
  critical: 4,
  high: 3,
  medium: 2,
  low: 1,
};

/** Numeric desirability of an atom for cold-start injection (higher = keep). */
export function bootstrapAtomScore(a: BootstrapAtom): number {
  const importance = IMPORTANCE_WEIGHT[(a.importance ?? '').toLowerCase()] ?? 1.5;
  const verified = a.isVerified ? 1.5 : 0;
  const confidence = typeof a.confidence === 'number' ? a.confidence : 0.5;
  return importance + verified + confidence;
}

/**
 * Rank atoms for cold-start injection by importance / verification / confidence,
 * breaking ties by recency, and return the top `limit`. Pure and deterministic.
 */
export function rankBootstrapAtoms(atoms: BootstrapAtom[], limit: number): BootstrapAtom[] {
  const toTime = (v: Date | string | null | undefined): number => {
    if (!v) return 0;
    const t = v instanceof Date ? v.getTime() : Date.parse(v);
    return Number.isFinite(t) ? t : 0;
  };
  return [...atoms]
    .sort((a, b) => {
      const s = bootstrapAtomScore(b) - bootstrapAtomScore(a);
      if (s !== 0) return s;
      return toTime(b.createdAt) - toTime(a.createdAt);
    })
    .slice(0, Math.max(0, limit));
}

function clip(s: string, max: number): string {
  const t = (s ?? '').replace(/\s+/g, ' ').trim();
  return t.length <= max ? t : `${t.slice(0, max)}…`;
}

/** Compact per-file recall line: where a vault document is and what it is for. */
export interface VaultFileDigest {
  fileName: string;
  documentTitle: string;
  programName?: string | null;
  folderId?: string | null;
  ctdSection?: string | null;
  placementStatus: string;
  /** extracted | extraction_failed | cataloged | uncataloged */
  catalogStatus: string;
  documentKind?: string | null;
  purpose?: string | null;
  /** suggested | confirmed | corrected (S4); absent or null reads as not confirmed. */
  catalogState?: string | null;
}

/** A chat-uploaded file the client attached in some past conversation. */
export interface ChatUploadRecallDigest {
  fileName: string;
  fileId: string | null;
  uploadedAt?: string | null;
}

/**
 * A bounded sample of the org's vault files together with the scope-wide
 * numbers it was drawn from.
 *
 * The recall block lists the twelve most recent files under a heading that
 * reads as the complete set. For an org with more than twelve it was not:
 * the withheld ones were the OLDEST, which are exactly the files a client
 * expects AnA to still know about and the ones she would otherwise answer
 * "there is no such document" about. The sample is fine; presenting it as
 * the whole is not, so the scope travels with it.
 */
export interface VaultFileScope {
  files: VaultFileDigest[];
  /** Live documents in the org — not `files.length`. */
  total: number;
  /** How many the sample leaves out. */
  withheld: number;
  notYetStudied: number;
  extractionFailed: number;
  unfiled: number;
}

/** Chat uploads for recall, and whether the limit hid any. */
export interface ChatUploadScope {
  uploads: ChatUploadRecallDigest[];
  hasMore: boolean;
}

export interface SessionBootstrapParts {
  workingMemorySummary?: string | null;
  projectAtoms: BootstrapAtom[];
  clientAtoms: BootstrapAtom[];
  outcomeLessons: OutcomeLesson[];
  /** Project-vault files on record (document catalog); omitted when the catalog is off. */
  vaultFiles?: VaultFileScope;
  /** Files the client attached in past conversations — reachable, not yet filed. */
  chatUploads?: ChatUploadScope;
  atomLimit?: number;
}

/**
 * The sentence that stops a sample being read as a total.
 *
 * Returns '' only when the listing IS the scope and nothing in it needs
 * attention — i.e. when there is genuinely nothing the lines above do not
 * already say. Every other case names a number, because "12 files" and
 * "12 of 40 files, 19 never studied" lead to different behaviour and the
 * block used to render both identically.
 */
export function formatVaultScopeLine(scope: VaultFileScope): string {
  const parts: string[] = [];
  if (scope.withheld > 0) {
    parts.push(
      `Showing ${scope.files.length} of ${scope.total} files on record — ` +
        `${scope.withheld} older one(s) are NOT listed above. Never answer "no such document" ` +
        `from this list alone: use list_project_documents or search_project_documents first.`,
    );
  } else {
    parts.push(`${scope.total} file(s) on record — this is all of them.`);
  }
  const flags: string[] = [];
  if (scope.notYetStudied > 0) flags.push(`${scope.notYetStudied} not yet studied`);
  if (scope.unfiled > 0) flags.push(`${scope.unfiled} unfiled`);
  if (scope.extractionFailed > 0) flags.push(`${scope.extractionFailed} with failed extraction`);
  if (flags.length) parts.push(`${flags.join(', ')} (across all of them, not just the ones above).`);
  return parts.join(' ');
}

/**
 * Whose description this is (S4). AnA's own suggestion is recalled as hers and
 * unconfirmed, so she does not repeat it to the user as an established fact.
 */
function catalogProvenance(state: string | null | undefined): string {
  if (state === 'confirmed') return ' (confirmed by a person)';
  if (state === 'corrected') return ' (corrected by a person)';
  return ' (your suggestion, not yet confirmed by a person)';
}

/** One recall line per file — location first, then what it is (or, honestly, that it awaits study). */
export function formatVaultFileLine(f: VaultFileDigest): string {
  const filed = [f.folderId, f.ctdSection].filter(Boolean).join(' · ');
  // A suggested folder is a proposal no person has confirmed; said so (S4).
  const location =
    f.placementStatus === 'unfiled'
      ? 'unfiled — needs review'
      : f.placementStatus === 'suggested'
        ? `${filed ? `${filed}, ` : ''}filing suggested, not yet confirmed by a person`
        : filed || f.placementStatus;
  const name = clip(f.documentTitle || f.fileName, 90);
  const where = `${f.programName ? `${clip(f.programName, 40)} / ` : ''}${location}`;
  if (f.catalogStatus === 'cataloged') {
    const what = [f.documentKind, f.purpose].filter(Boolean).map(s => clip(String(s), 160)).join(' — ');
    return `- **${name}** (${where}): ${what || 'cataloged'}${catalogProvenance(f.catalogState)}. ` +
      'Automatic scope: legacy value-presence check; label/context verification is not recorded; scientific qualification is unassessed.';
  }
  if (f.catalogStatus === 'extraction_failed') {
    return `- **${name}** (${where}): extraction FAILED — the content is not readable yet; say so if asked.`;
  }
  return `- **${name}** (${where}): not yet studied — read it in full and catalog it when it becomes relevant.`;
}

/**
 * Format the bootstrap context block injected at session start. Pure: takes
 * already-loaded parts and renders compact markdown. Returns '' when there is
 * genuinely nothing to recall (so callers can omit the block entirely).
 */
export function formatSessionBootstrap(parts: SessionBootstrapParts): string {
  const atomLimit = parts.atomLimit ?? 6;
  const lines: string[] = [];

  if (parts.workingMemorySummary && parts.workingMemorySummary.trim()) {
    lines.push('### Where we left off');
    lines.push(clip(parts.workingMemorySummary, 1200));
  }

  const project = rankBootstrapAtoms(parts.projectAtoms, atomLimit);
  if (project.length) {
    lines.push('### Project memory (most important)');
    for (const a of project) {
      lines.push(`- **${clip(a.title, 120)}**${a.category ? ` _(${a.category})_` : ''}: ${clip(a.content, 240)}`);
    }
  }

  const client = rankBootstrapAtoms(parts.clientAtoms, Math.max(2, Math.floor(atomLimit / 2)));
  if (client.length) {
    lines.push('### Client memory (most important)');
    for (const a of client) {
      lines.push(`- **${clip(a.title, 120)}**${a.category ? ` _(${a.category})_` : ''}: ${clip(a.content, 240)}`);
    }
  }

  const vault = parts.vaultFiles;
  const files = (vault?.files ?? []).slice(0, 12);
  if (files.length) {
    lines.push('### Project files on record');
    for (const f of files) lines.push(formatVaultFileLine(f));
    /* The scope line before the how-to: what is missing from this list changes
       whether the reader should consult the tools at all. */
    if (vault) lines.push(`_${formatVaultScopeLine(vault)}_`);
    lines.push(
      '_Use list_project_documents for the full folder; read_project_document to study a file (all of it)._'
    );
  }

  const uploads = (parts.chatUploads?.uploads ?? []).slice(0, 8);
  if (uploads.length) {
    /* A chat upload is reachable but has no vault row, so it carries no filed
       location and no comprehension record — saying only "these exist" would
       invite the same "I can't see it" answer the catalog exists to end. Each
       line carries the id that reopens it and the fact that filing is what
       gives it a durable record. */
    lines.push('### Files the client sent in past conversations');
    for (const u of uploads) {
      lines.push(
        `- **${clip(u.fileName, 90)}**${u.fileId ? ` (${u.fileId})` : ''} — attached earlier, not filed into the vault.`
      );
    }
    if (parts.chatUploads?.hasMore) {
      lines.push(
        `_More than these ${uploads.length} were attached — list_project_documents returns the rest._`
      );
    }
    /* The retrieval corpus holds ONE bounded-prefix atom per chat upload, so
       "it is searchable" is true of its opening and false of the rest. Filing
       it runs the canonical vault ingest, which chunks and page-numbers all of
       it — the difference matters before she answers from a search. */
    lines.push(
      '_Only the OPENING of each is in the retrieval index. Reopen one with read_uploaded_document; ' +
        'file_chat_upload_to_vault files it and indexes all of it, page by page._'
    );
  }

  const lessons = parts.outcomeLessons.filter(l => l.lessonsLearned && l.lessonsLearned.trim()).slice(0, 5);
  if (lessons.length) {
    lines.push('### What I learned on past work here');
    for (const l of lessons) {
      const tag = l.documentType ? `${l.capabilityKey}/${l.documentType}` : l.capabilityKey;
      lines.push(`- (${tag}, ${l.outcome}) ${clip(l.lessonsLearned!, 220)}`);
    }
  }

  if (lines.length === 0) return '';
  return ['## Session memory — picking up where we left off', ...lines].join('\n');
}
